namespace SmartProperty.Domain.PropertyRegistry;

/// <summary>
/// One photo of a property. A property has an ordered group of them; the first in order is its cover.
/// </summary>
/// <remarks>
/// The picture itself is not in the database. <see cref="StorageKey"/> names where the file is kept, and the key is
/// generated by the platform (never taken from the client), so it is safe to use as a path. The content type is what
/// the file's own bytes say it is, not what the client declared.
/// </remarks>
public sealed class PropertyImage
{
    public const int MaxPerProperty = 20;
    public const long MaxSizeBytes = 5L * 1024 * 1024;
    public const int MaxFileNameLength = 200;
    public const int MaxStorageKeyLength = 300;

    public const string Jpeg = "image/jpeg";
    public const string Png = "image/png";
    public const string WebP = "image/webp";

    public static readonly IReadOnlyList<string> AllowedContentTypes = [Jpeg, Png, WebP];

    private PropertyImage()
    {
        StorageKey = string.Empty;
        FileName = string.Empty;
        ContentType = string.Empty;
    }

    public PropertyImage(
        Guid id,
        Guid propertyId,
        string storageKey,
        string? fileName,
        string contentType,
        long sizeBytes,
        int sortOrder,
        DateTimeOffset createdAt)
    {
        if (id == Guid.Empty)
        {
            throw new ArgumentException("Image id must not be empty.", nameof(id));
        }

        if (propertyId == Guid.Empty)
        {
            throw new ArgumentException("Property id must not be empty.", nameof(propertyId));
        }

        if (string.IsNullOrWhiteSpace(storageKey) || storageKey.Length > MaxStorageKeyLength)
        {
            throw new ArgumentException(
                $"Storage key is required and must not exceed {MaxStorageKeyLength} characters.", nameof(storageKey));
        }

        if (!AllowedContentTypes.Contains(contentType, StringComparer.Ordinal))
        {
            throw new ArgumentOutOfRangeException(nameof(contentType), contentType, "Image type is not supported.");
        }

        if (sizeBytes is <= 0 or > MaxSizeBytes)
        {
            throw new ArgumentOutOfRangeException(
                nameof(sizeBytes), sizeBytes, $"Image size must be between 1 and {MaxSizeBytes} bytes.");
        }

        if (sortOrder < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(sortOrder), sortOrder, "Sort order must not be negative.");
        }

        Id = id;
        PropertyId = propertyId;
        StorageKey = storageKey.Trim();
        FileName = NormalizeFileName(fileName);
        ContentType = contentType;
        SizeBytes = sizeBytes;
        SortOrder = sortOrder;
        CreatedAt = createdAt;
    }

    public Guid Id { get; private set; }
    public Guid PropertyId { get; private set; }
    public string StorageKey { get; private set; }

    /// <summary>The name the client gave the file, for display. Never used to locate it.</summary>
    public string FileName { get; private set; }

    public string ContentType { get; private set; }
    public long SizeBytes { get; private set; }

    /// <summary>Position in the property's group, lowest first. The lowest is the cover.</summary>
    public int SortOrder { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }

    public void MoveTo(int sortOrder)
    {
        if (sortOrder < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(sortOrder), sortOrder, "Sort order must not be negative.");
        }

        SortOrder = sortOrder;
    }

    /// <summary>The file extension, with the dot, for a supported content type.</summary>
    public static string ExtensionOf(string contentType)
    {
        return contentType switch
        {
            Jpeg => ".jpg",
            Png => ".png",
            WebP => ".webp",
            _ => throw new ArgumentOutOfRangeException(nameof(contentType), contentType, "Image type is not supported.")
        };
    }

    // Only the last path segment is kept, so a client cannot smuggle a directory into the displayed name.
    private static string NormalizeFileName(string? fileName)
    {
        if (string.IsNullOrWhiteSpace(fileName))
        {
            return "image";
        }

        var name = fileName.Replace('\\', '/');
        name = name[(name.LastIndexOf('/') + 1)..].Trim();

        if (name.Length == 0)
        {
            return "image";
        }

        return name.Length <= MaxFileNameLength ? name : name[..MaxFileNameLength];
    }
}
